<?php
namespace EventFlow\Infrastructure\Persistence\WordPress;
use DateTimeImmutable;use DateTimeZone;use EventFlow\Application\Persistence\EventScope;use EventFlow\Application\Provider\{NormalizedProviderWebhook,ProviderDispatchMessage,ProviderEventRecord,ProviderException,ProviderOutcome,ProviderRepository,ProviderSendResult};use EventFlow\Infrastructure\Persistence\{PersistenceException,TableName};
final class WpdbProviderRepository extends AbstractWpdbRepository implements ProviderRepository
{
 public function lockQueuedMessage(EventScope $s,int $id,string $provider,DateTimeImmutable $now):ProviderDispatchMessage{$m=$this->table(TableName::MESSAGES);$a=$this->table(TableName::MESSAGE_DELIVERY_ATTEMPTS);$r=$this->database->fetchRow("SELECT message_id,channel,recipient_address,subject,rendered_content,delivery_status,attempt_count FROM {$m} WHERE event_id=%d AND message_id=%d LIMIT 1 FOR UPDATE",[$s->eventId,$id]);if($r===null)throw new ProviderException('resource_not_found');if(!in_array($r['delivery_status'],['queued','retry_pending'],true))throw new ProviderException('message_not_retryable');$attempt=(int)$r['attempt_count']+1;$key=hash('sha256',$provider.':'.$s->eventId.':'.$id.':'.$attempt);$ts=$this->ts($now);if($this->database->execute("INSERT INTO {$a} (event_id,message_id,attempt_number,provider,attempt_status,provider_request_id,attempted_at,created_at) VALUES (%d,%d,%d,%s,'started',%s,%s,%s)",[$s->eventId,$id,$attempt,$provider,$key,$ts,$ts])!==1)throw new PersistenceException('delivery_attempt_create_failed');$this->database->execute("UPDATE {$m} SET delivery_status='processing',provider=%s,attempt_count=%d,processing_at=%s,updated_at=%s WHERE event_id=%d AND message_id=%d",[$provider,$attempt,$ts,$ts,$s->eventId,$id]);return new ProviderDispatchMessage($s,$id,(string)$r['channel'],(string)$r['recipient_address'],$r['subject']===null?null:(string)$r['subject'],(string)$r['rendered_content'],$attempt,$key);}
 public function recordSendResult(ProviderDispatchMessage $m,string $provider,ProviderSendResult $r,DateTimeImmutable $now):void{$a=$this->table(TableName::MESSAGE_DELIVERY_ATTEMPTS);$messages=$this->table(TableName::MESSAGES);$ts=$this->ts($now);$attemptStatus=match($r->outcome){ProviderOutcome::ACCEPTED=>'provider_accepted',ProviderOutcome::DEFINITIVE_FAILURE=>'failed',ProviderOutcome::AMBIGUOUS=>'timed_out'};$this->database->execute("UPDATE {$a} SET attempt_status=%s,provider_message_id=".($r->providerMessageId===null?'NULL':'%s').",response_code=".($r->responseCode===null?'NULL':'%s').",error_code=".($r->errorCode===null?'NULL':'%s').",provider_accepted_at=".($r->outcome===ProviderOutcome::ACCEPTED?'%s':'NULL').",completed_at=%s WHERE event_id=%d AND message_id=%d AND provider=%s AND provider_request_id=%s AND attempt_status='started'",array_values(array_filter([$attemptStatus,$r->providerMessageId,$r->responseCode,$r->errorCode,$r->outcome===ProviderOutcome::ACCEPTED?$ts:null,$ts,$m->eventScope->eventId,$m->messageId,$provider,$m->requestKey],fn($v)=>$v!==null)));$status=match($r->outcome){ProviderOutcome::ACCEPTED=>'provider_accepted',ProviderOutcome::DEFINITIVE_FAILURE=>'failed',ProviderOutcome::AMBIGUOUS=>'uncertain'};$this->database->execute("UPDATE {$messages} SET delivery_status=%s,provider_message_id=".($r->providerMessageId===null?'provider_message_id':'%s').",provider_accepted_at=".($r->outcome===ProviderOutcome::ACCEPTED?'%s':'provider_accepted_at').",failed_at=".($r->outcome===ProviderOutcome::DEFINITIVE_FAILURE?'%s':'failed_at').",updated_at=%s WHERE event_id=%d AND message_id=%d",array_values(array_filter([$status,$r->providerMessageId,$r->outcome===ProviderOutcome::ACCEPTED?$ts:null,$r->outcome===ProviderOutcome::DEFINITIVE_FAILURE?$ts:null,$ts,$m->eventScope->eventId,$m->messageId],fn($v)=>$v!==null)));}
 public function correlate(EventScope $s,string $provider,?string $messageId,?string $requestId):?array{$a=$this->table(TableName::MESSAGE_DELIVERY_ATTEMPTS);$where=$messageId!==null?'provider_message_id=%s':($requestId!==null?'provider_request_id=%s':'1=0');$value=$messageId??$requestId;$r=$this->database->fetchRow("SELECT delivery_attempt_id attempt_id,message_id FROM {$a} WHERE event_id=%d AND provider=%s AND {$where} ORDER BY delivery_attempt_id DESC LIMIT 1",$value===null?[$s->eventId,$provider]:[$s->eventId,$provider,$value]);return $r;}
 public function storeEvent(NormalizedProviderWebhook $e,int $messageId,?int $attemptId,DateTimeImmutable $received):ProviderEventRecord{$t=$this->table(TableName::PROVIDER_EVENTS);$key=$e->dedupeKey();$old=$this->database->fetchRow("SELECT provider_event_id,message_id,normalized_event_type FROM {$t} WHERE provider=%s AND event_dedupe_key=%s LIMIT 1 FOR UPDATE",[$e->provider,$key]);if($old!==null)return new ProviderEventRecord((int)$old['provider_event_id'],(int)$old['message_id'],$key,(string)$old['normalized_event_type'],true);$ts=$this->ts($received);$sql="INSERT INTO {$t} (event_id,message_id,delivery_attempt_id,provider,provider_event_key,event_dedupe_key,provider_event_type,normalized_event_type,provider_status,reason_code,reason_message,provider_occurred_at,received_at,processing_status,created_at) VALUES (%d,%d,".($attemptId===null?'NULL':'%d').",%s,".($e->nativeEventKey===null?'NULL':'%s').",%s,%s,%s,".($e->providerStatus===null?'NULL':'%s').",".($e->reasonCode===null?'NULL':'%s').",".($e->reasonMessage===null?'NULL':'%s').",".($e->occurredAt===null?'NULL':'%s').",%s,'pending',%s)";$p=[$e->eventScope->eventId,$messageId];foreach([$attemptId,$e->provider,$e->nativeEventKey,$key,$e->providerEventType,$e->normalizedType,$e->providerStatus,$e->reasonCode,$e->reasonMessage,$e->occurredAt?->format('Y-m-d H:i:s'),$ts,$ts]as$v)if($v!==null)$p[]=$v;if($this->database->execute($sql,$p)!==1)throw new PersistenceException('provider_event_create_failed');return new ProviderEventRecord($this->database->lastInsertId(),$messageId,$key,$e->normalizedType);}
 public function applyEvent(EventScope $s,ProviderEventRecord $e,DateTimeImmutable $at):void{$events=$this->table(TableName::PROVIDER_EVENTS);$messages=$this->table(TableName::MESSAGES);$ts=$this->ts($at);$column=match($e->normalizedType){'delivered'=>'delivered_at','bounced'=>'bounced_at','failed'=>'failed_at',default=>null};$allowed=match($e->normalizedType){'failed'=>['queued','processing','provider_accepted','uncertain','failed'],'delivered'=>['queued','processing','provider_accepted','uncertain','failed','delivered'],'bounced'=>['queued','processing','provider_accepted','uncertain','failed','delivered','bounced'],default=>[]};if($column!==null){$states=implode(',',array_fill(0,count($allowed),'%s'));$this->database->execute("UPDATE {$messages} SET delivery_status=%s,{$column}=COALESCE({$column},%s),updated_at=%s WHERE event_id=%d AND message_id=%d AND delivery_status IN ({$states})",[$e->normalizedType,$ts,$ts,$s->eventId,$e->messageId,...$allowed]);}$this->database->execute("UPDATE {$events} SET processing_status='processed',processed_at=%s WHERE event_id=%d AND provider_event_id=%d AND processing_status='pending'",[$ts,$s->eventId,$e->providerEventId]);}
 private function ts(DateTimeImmutable $d):string{return $d->setTimezone(new DateTimeZone('UTC'))->format('Y-m-d H:i:s');}
}
